"from bs4 import BeautifulSoup\n\nwith open(\"tests/workday/Systems Software Engineer - New College Grad 2026.htm\", \"r\", encoding=\"utf-8\", errors=\"ignore\") as f:\n    html = f.read()\n    soup = BeautifulSoup(html, \"html.parser\")\n\n# Check all sections and their add buttons\nfor sec_name in [\"Work Experience\", \"Education\", \"Websites\"]:\n    headings = [el for el in soup.find_all(['h1', 'h2', 'h3', 'h4', 'legend', 'label', 'div']) if el.get_text(strip=True).lower() == sec_name.lower()]\n    print(f\"\\n--- Section: {sec_name} ---\")\n    for h in headings:\n        # Find closest section container\n        container = h.find_parent(['div', 'fieldset'])\n        while container and not container.find('button'):\n            container = container.find_parent(['div', 'fieldset'])\n        if container:\n            btns = container.find_all('button')\n            for b in btns:\n                print(f\"  Button: text={b.get_text(strip=True)!r}, auto_id={b.get('data-automation-id')!r}, aria={b.get('aria-label')!r}\")\n"